CREATE OR REPLACE FUNCTION public.get_public_inspection_approval(p_inspection_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$ DECLARE v_insp public.bicycle_inspections; v_issues jsonb; v_bike text; v_offered_count integer; BEGIN SELECT * INTO v_insp FROM public.bicycle_inspections WHERE id = p_inspection_id; IF v_insp.id IS NULL THEN RETURN jsonb_build_object('error','not_found'); END IF; IF v_insp.released_to_customer_at IS NULL THEN RETURN jsonb_build_object('error','not_released'); END IF; SELECT COALESCE(jsonb_agg(jsonb_build_object('id',i.id,'issue_description',i.issue_description,'estimated_cost',i.estimated_cost,'status',i.status,'customer_response',i.customer_response,'offered_to_receiver_at',i.offered_to_receiver_at,'receiver_approved_at',i.receiver_approved_at,'receiver_declined_at',i.receiver_declined_at) ORDER BY i.created_at),'[]'::jsonb) INTO v_issues FROM public.inspection_issues i WHERE i.inspection_id=v_insp.id; SELECT count(*) INTO v_offered_count FROM public.inspection_issues i WHERE i.inspection_id=v_insp.id AND i.offered_to_receiver_at IS NOT NULL AND i.receiver_approved_at IS NULL AND i.receiver_declined_at IS NULL; v_bike := NULLIF(trim(concat_ws(' ',v_insp.bike_brand,v_insp.bike_model)),''); RETURN jsonb_build_object('inspection_id',v_insp.id,'order_id',v_insp.order_id,'status',v_insp.status,'awaiting_receiver_count',v_offered_count,'customer_name',v_insp.customer_name,'bike',v_bike,'frame_size',v_insp.frame_size,'reference',v_insp.reference,'report_url',v_insp.report_url,'inspection_type',v_insp.inspection_type,'service_decision',v_insp.service_decision,'issues',v_issues); END; $$;
CREATE OR REPLACE FUNCTION public.submit_public_inspection_approval(p_inspection_id uuid, p_approved_issue_ids uuid[], p_service_decision text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_insp public.bicycle_inspections; v_result jsonb; v_open integer; BEGIN SELECT * INTO v_insp FROM public.bicycle_inspections WHERE id=p_inspection_id FOR UPDATE; IF v_insp.id IS NULL THEN RETURN jsonb_build_object('error','not_found'); END IF; IF v_insp.released_to_customer_at IS NULL THEN RETURN jsonb_build_object('error','not_released'); END IF; IF v_insp.inspection_type = 'inspection_only' AND v_insp.service_decision = 'pending' THEN IF p_service_decision IS NULL OR p_service_decision NOT IN ('accepted','declined') THEN RETURN jsonb_build_object('error','service_choice_required'); END IF; ELSE IF p_service_decision IS NOT NULL AND p_service_decision IS DISTINCT FROM v_insp.service_decision THEN RETURN jsonb_build_object('error','service_choice_already_recorded'); END IF; END IF; SELECT count(*) INTO v_open FROM public.inspection_issues WHERE inspection_id=p_inspection_id AND status='pending'; IF v_open=0 AND v_insp.service_decision <> 'pending' THEN RETURN jsonb_build_object('error','already_submitted'); END IF; v_result := public.submit_public_inspection_approval(p_inspection_id,p_approved_issue_ids); IF v_result->>'success' IS DISTINCT FROM 'true' THEN RETURN v_result; END IF; IF v_insp.inspection_type='inspection_only' AND v_insp.service_decision='pending' THEN UPDATE public.bicycle_inspections SET service_decision=p_service_decision, status=CASE WHEN p_service_decision='accepted' AND v_result->>'approved'='0' THEN 'awaiting_repair' WHEN p_service_decision='declined' AND v_result->>'approved'='0' AND v_result->>'declined'='0' THEN 'ship_as_is' ELSE status END WHERE id=p_inspection_id; END IF; RETURN v_result || jsonb_build_object('service_decision',COALESCE(p_service_decision,v_insp.service_decision)); END; $$;
REVOKE ALL ON FUNCTION public.submit_public_inspection_approval(uuid,uuid[]) FROM PUBLIC, anon, authenticated; REVOKE ALL ON FUNCTION public.submit_public_inspection_approval(uuid,uuid[],text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.submit_public_inspection_approval(uuid,uuid[],text) TO anon, authenticated;
CREATE OR REPLACE FUNCTION public.guard_inspection_service_status() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.inspection_type='inspection_only' AND NEW.service_decision='pending' AND NEW.status IN ('awaiting_parts','awaiting_repair','in_repair','cleaning','repaired','ship_as_is','inspected') THEN RAISE EXCEPTION 'Service choice is still pending'; END IF; IF NEW.inspection_type='inspection_only' AND NEW.service_decision='declined' AND NEW.status='cleaning' THEN RAISE EXCEPTION 'Declined service cannot enter cleaning'; END IF; RETURN NEW; END; $$; CREATE TRIGGER guard_inspection_service_status BEFORE UPDATE OR INSERT ON public.bicycle_inspections FOR EACH ROW EXECUTE FUNCTION public.guard_inspection_service_status();